:root {
  --bg: #0a0f1c; --panel: #101a2e; --panel2: #0d1526; --line: #22304d;
  --ink: #e7edf7; --mut: #8fa3bf; --dim: #647693;
  --acc: #2dd4bf; --acc-dim: #1d7a6e; --amber: #f5b942; --red: #f4707a; --green: #4ade80;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace;
  --sans: -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
* { box-sizing: border-box; }
html { background: var(--bg); }
body { margin: 0; background: var(--bg); color: var(--ink); font: 15px/1.55 var(--sans); }
a { color: var(--acc); }
.top { border-bottom: 1px solid var(--line); background: linear-gradient(180deg, #0e1830, #0a0f1c); }
.top-in { max-width: 1180px; margin: 0 auto; padding: 20px 20px 16px; display: flex; flex-wrap: wrap; gap: 16px; align-items: flex-end; justify-content: space-between; }
.brand { display: flex; gap: 14px; align-items: center; }
.pulse { width: 14px; height: 14px; border-radius: 50%; background: var(--acc); box-shadow: 0 0 0 0 rgba(45,212,191,.6); animation: pl 2.2s infinite; flex: none; }
@keyframes pl { 0% { box-shadow: 0 0 0 0 rgba(45,212,191,.55); } 70% { box-shadow: 0 0 0 12px rgba(45,212,191,0); } 100% { box-shadow: 0 0 0 0 rgba(45,212,191,0); } }
h1 { margin: 0; font: 700 30px/1.05 var(--sans); letter-spacing: .14em; }
.sub { margin: 5px 0 0; color: var(--mut); font-size: 14px; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; }
.chip { border: 1px solid var(--line); border-radius: 999px; padding: 5px 12px; font: 600 12px/1.4 var(--mono); color: var(--ink); background: #0d1830; white-space: nowrap; }
.chip b { color: var(--acc); font-weight: 700; }
main { max-width: 1180px; margin: 0 auto; padding: 0 20px 40px; }
.method { margin: 14px 0 12px; border: 1px solid var(--line); border-left: 3px solid var(--acc); border-radius: 10px; background: var(--panel); padding: 12px 20px; }
.method h2 { margin: 0 0 6px; font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: var(--acc); }
.method p { margin: 0 0 8px; color: #c6d2e6; font-size: 14.5px; }
.method p:last-child { margin-bottom: 0; }
.method-grid { display: grid; grid-template-columns: minmax(0, 1fr) 400px; gap: 20px; align-items: start; }
@media (max-width: 860px) { .method-grid { grid-template-columns: 1fr; } }
.curve-chart { margin: 0; }
.curve-chart svg { display: block; width: 100%; height: auto; }
.curve-chart figcaption { color: var(--mut); font: 11.5px var(--sans); margin-top: 4px; }
.method-meta { margin-top: 8px !important; color: var(--mut) !important; font: 12.5px var(--mono); }
.method.collapsed { padding: 8px 20px; }
.method.collapsed .method-grid, .method.collapsed .method-meta { display: none; }
.method.collapsed h2 { margin: 0; }
.method.collapsed h2::after { content: ' — hidden while a protocol is open; close the detail to read it again'; text-transform: none; letter-spacing: 0; color: var(--mut); }
.tabs { display: flex; gap: 6px; margin: 4px 0 10px; }
.tab { border: 1px solid var(--line); background: transparent; color: var(--mut); border-radius: 8px; padding: 8px 16px; font: 600 13.5px var(--sans); cursor: pointer; }
.tab.on { background: var(--acc); border-color: var(--acc); color: #06231d; }
.controls { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.controls input[type=search], .controls select { background: var(--panel); border: 1px solid var(--line); color: var(--ink); border-radius: 8px; padding: 8px 11px; font: 14px var(--sans); }
.controls input[type=search] { flex: 1 1 220px; min-width: 180px; }
.controls select { max-width: 220px; }
.wl { display: inline-flex; gap: 6px; align-items: center; color: var(--mut); font-size: 13.5px; cursor: pointer; white-space: nowrap; }
.wl input { accent-color: var(--acc); width: 16px; height: 16px; }
.count { color: var(--mut); font: 12.5px var(--mono); margin: 8px 0 6px; }
.table-wrap { border: 1px solid var(--line); border-radius: 10px; overflow: auto; background: var(--panel2); }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
thead th { text-align: left; padding: 10px 12px; color: var(--mut); font: 600 11.5px var(--sans); letter-spacing: .09em; text-transform: uppercase; border-bottom: 1px solid var(--line); background: #0e1930; position: sticky; top: 0; }
thead th.sortable { cursor: pointer; }
thead th.sortable:hover { color: var(--ink); }
thead th.sorted { color: var(--acc); }
tbody td { padding: 9px 12px; border-bottom: 1px solid #16223c; vertical-align: middle; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: #13203c; }
tbody tr.sel { background: #12294a; box-shadow: inset 3px 0 0 var(--acc); }
.num { text-align: right; font-family: var(--mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
th.num { text-align: right; }
.rank { display: inline-block; min-width: 30px; text-align: center; border-radius: 6px; padding: 2px 6px; font: 700 13px var(--mono); background: #1a2c4e; color: #c6d2e6; }
tr.r1 .rank { background: var(--amber); color: #231a02; }
tr.r2 .rank, tr.r3 .rank { background: #2b3f66; color: #fff; }
.pname { font-weight: 650; }
.pslug { color: var(--dim); font: 11.5px var(--mono); }
.wltag { display: inline-block; margin-left: 7px; padding: 1px 7px; border-radius: 999px; background: #123f38; color: var(--acc); font: 700 10.5px var(--sans); letter-spacing: .06em; vertical-align: 1px; }
.cat { color: #b9c7de; white-space: nowrap; }
.pill { display: inline-block; border: 1px solid var(--line); border-radius: 999px; padding: 1px 8px; margin: 1px 3px 1px 0; font: 11.5px var(--sans); color: #b9c7de; white-space: nowrap; }
.up { color: var(--green); } .dn { color: var(--red); }
.impl { font-weight: 700; color: #fff; }
.mult { color: var(--mut); }
.empty { color: var(--mut); padding: 18px; text-align: center; }
.detail { border: 1px solid var(--acc-dim); border-radius: 10px; background: #0e1a2c; padding: 14px 20px; margin: 4px 0 14px; }
.detail h2 { margin: 0; font-size: 22px; }
.detail h2 .pslug { font-size: 13px; }
.detail .dmeta { color: var(--mut); margin: 4px 0 10px; font-size: 13.5px; }
.dgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; margin-bottom: 10px; }
.dstat { border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; background: var(--panel); }
.dstat .k { color: var(--mut); font-size: 11px; letter-spacing: .09em; text-transform: uppercase; }
.dstat .v { font: 700 17px var(--mono); margin-top: 2px; }
.detail h3 { margin: 10px 0 8px; font-size: 13px; letter-spacing: .1em; text-transform: uppercase; color: var(--acc); }
.math { font: 13.5px var(--mono); background: #0a1224; border: 1px solid var(--line); border-radius: 8px; padding: 10px 14px; line-height: 1.9; overflow-x: auto; white-space: nowrap; }
.math b { color: var(--amber); }
.comps { width: auto; }
.comps td, .comps th { padding: 6px 14px 6px 0; border: none; }
.steps { margin: 0; padding: 0; list-style: none; counter-reset: st; }
.steps li { counter-increment: st; position: relative; padding: 5px 12px 5px 46px; border: 1px solid var(--line); border-radius: 8px; margin-bottom: 4px; background: var(--panel); }
.steps li::before { content: counter(st); position: absolute; left: 12px; top: 6px; width: 24px; height: 24px; border-radius: 50%; background: var(--acc); color: #06231d; font: 700 13px/24px var(--sans); text-align: center; }
.steps .ct { display: block; color: var(--mut); font: 12px var(--mono); margin-top: 3px; }
.live-note { color: var(--mut); font-size: 14px; margin: 0 0 12px; }
footer { margin-top: 26px; border-top: 1px solid var(--line); padding-top: 14px; color: var(--dim); font-size: 12.5px; }
footer p { margin: 4px 0; }
